package docking.dnd;

import java.awt.Point;
import java.awt.datatransfer.Transferable;
import java.awt.dnd.DragGestureEvent;
import java.awt.dnd.DragSourceDropEvent;
import java.awt.dnd.DragSourceListener;

/**
 * Interface to define a drag source.
 */
public interface Draggable {

    /**
     * Returns true if the object at the location in the DragGestureEvent
     * is draggable.
     *
     * @param event the event passed to a DragGestureListener when a platform-dependent
     *              Drag and Drop action initiating gesture has occurred on the
     *              Component it is tracking.
     * @see docking.dnd.DragGestureAdapter
     */
    boolean isStartDragOk(DragGestureEvent event);

    /**
     * Returns the DragSourceListener for the drag operation.
     */
    DragSourceListener getDragSourceListener();

    /**
     * Performs the move operation when the drag and drop operation completes.
     *
     * @see docking.dnd.DragSrcAdapter#dragDropEnd
     */
    void move();

    /**
     * Called when the drag operation exits the drop target without dropping.
     *
     * @param event the event containing information about the drop operation
     */
    void dragCanceled(DragSourceDropEvent event);

    /**
     * Returns the drag actions supported by this drag source.
     * Possible values are:
     * <ul>
     *     <li>DnDConstants.ACTION_MOVE</li>
     *     <li>DnDConstants.ACTION_COPY</li>
     *     <li>DnDConstants.ACTION_COPY_OR_MOVE</li>
     * </ul>
     *
     * @return the drag actions
     */
    int getDragAction();

    /**
     * Returns the object to transfer.
     *
     * @param location the location of the object to transfer
     * @return the object to transfer
     */
    Transferable getTransferable(Point location);
}
